export function withSpaceGuard<T>(dir: string, fn: () => T): T {
  // instrument L0, § 8 : la demande est prépubliée AVANT la toute première tentative de
  // mkdirSync(path), conservée pendant l'acquisition et le rappel sous garde, retirée en
  // finally. Un EEXIST reçu par un concurrent sur N est postérieur à la création de N,
  // donc à cette demande.
  mkdirSync(dir, { recursive: true });
  const demandeL0 = l0PublierDemande(join(dir, N_GUARD));
  l0DemandesPrepubliees.set(demandeL0.lock_path, demandeL0.wait_id);
  try {
    return withSpaceGuardSousDemandeL0(dir, fn);
  } finally {
    l0DemandesPrepubliees.delete(demandeL0.lock_path);
    l0RetirerDemande(demandeL0);
  }
}

