/* ==================================================================== instrument L0
 *
 * Plan v2 (PLAN-INSTRUMENT-EEXIST.md 5b12939a…). Injecté par le champ `control` des
 * trois mutants de course, sur copie jetable seulement. Il ne vit jamais dans le dépôt.
 *
 * Une barrière de contrôle se termine sur sa condition métier, ou sur un témoin LIÉ À
 * SA DEMANDE COURANTE (`wait_id`) prouvant qu'un autre processus a tenté de créer le
 * verrou exact et a reçu `EEXIST`. À dix secondes, elle lève.
 *
 * Magasin d'un verrou, hors dépôt et hors espace de runs :
 *
 *   <tmpdir>/l0-temoins-eexist/<sha256 complet de resolve(verrou)>/
 *     demandes/<wait_id>.json            une par attente vivante
 *     temoins/<wait_id>.<emitter_pid>.json
 *     journal                            ordre des événements, par ajout (O_APPEND)
 *
 * `withSpaceGuard` prépublie sa demande AVANT sa toute première tentative de `mkdirSync`
 * (§ 8) : un concurrent ne peut recevoir EEXIST sur N qu'après la création de N, donc
 * après cette demande. Aucune marge de 500 ms n'intervient.
 */

class TemoinSansCauseError extends Error {}

const L0_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** Demandes prépubliées par `withSpaceGuard` dans CE processus : verrou absolu → wait_id. */
const l0DemandesPrepubliees = new Map<string, string>();

function l0Resoudre(verrou: string): string {
  return process.getBuiltinModule("node:path").resolve(verrou);
}

/** Le magasin d'un verrou : SHA-256 complet de son chemin absolu. */
function l0Magasin(verrou: string): string {
  const os = process.getBuiltinModule("node:os");
  const p = process.getBuiltinModule("node:path");
  const c = process.getBuiltinModule("node:crypto");
  const empreinte = c.createHash("sha256").update(l0Resoudre(verrou)).digest("hex");
  return p.join(os.tmpdir(), "l0-temoins-eexist", empreinte);
}

/**
 * Le journal d'ordre. Un ajout O_APPEND est atomique et ordonné par le noyau : l'ordre
 * des lignes EST l'ordre des événements, sans comparaison d'horloges entre processus.
 */
function l0Journal(verrou: string, ligne: string): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  const m = l0Magasin(verrou);
  fs.mkdirSync(m, { recursive: true });
  fs.appendFileSync(p.join(m, "journal"), `${ligne} pid=${process.pid}\n`);
}

/** Écrit sous un nom temporaire propre, puis rend visible par `rename`. */
function l0EcrireAtomique(dossier: string, nom: string, corps: string): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  fs.mkdirSync(dossier, { recursive: true });
  const provisoire = p.join(dossier, `.${nom}.${process.pid}.tmp`);
  fs.writeFileSync(provisoire, corps);
  fs.renameSync(provisoire, p.join(dossier, nom));
}

type L0Demande = { wait_id: string; lock_path: string };

/** Publie une demande pour ce verrou. Le journal est écrit APRÈS le `rename`. */
function l0PublierDemande(verrou: string): L0Demande {
  const p = process.getBuiltinModule("node:path");
  const c = process.getBuiltinModule("node:crypto");
  const wait_id = c.randomUUID();
  const lock_path = l0Resoudre(verrou);
  l0EcrireAtomique(
    p.join(l0Magasin(verrou), "demandes"),
    `${wait_id}.json`,
    JSON.stringify({ wait_id, lock_path, waiter_pid: process.pid }),
  );
  l0Journal(verrou, `demande ${wait_id}`);
  return { wait_id, lock_path };
}

function l0RetirerDemande(d: L0Demande): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  fs.rmSync(p.join(l0Magasin(d.lock_path), "demandes", `${d.wait_id}.json`), { force: true });
  l0Journal(d.lock_path, `retrait ${d.wait_id}`);
}

/** Les demandes valides du verrou exact : nom, contenu, PID positif et verrou cohérents. */
function l0DemandesValides(verrou: string): string[] {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  const dossier = p.join(l0Magasin(verrou), "demandes");
  let noms: string[];
  try {
    noms = fs.readdirSync(dossier);
  } catch {
    return [];
  }
  const valides: string[] = [];
  for (const nom of noms.sort()) {
    const m = /^(.+)\.json$/.exec(nom);
    if (!m || nom.startsWith(".") || !L0_UUID.test(m[1])) continue;
    let d: { wait_id?: unknown; lock_path?: unknown; waiter_pid?: unknown };
    try {
      d = JSON.parse(fs.readFileSync(p.join(dossier, nom), "utf-8"));
    } catch {
      continue;
    }
    if (d?.wait_id !== m[1]) continue;
    if (typeof d.lock_path !== "string" || l0Resoudre(d.lock_path) !== l0Resoudre(verrou)) continue;
    if (!Number.isInteger(d.waiter_pid) || (d.waiter_pid as number) <= 0) continue;
    valides.push(m[1]);
  }
  return valides;
}

/**
 * Le producteur (§ 6, § 7). Il n'émet que sur la cause réelle d'un `mkdir` refusé :
 * l'erreur du `catch` courant, EEXIST, syscall mkdir, chemin égal au verrou. Sinon il
 * lève, sans rien émettre. Puis un témoin par demande valide du verrou exact.
 */
function temoignerEexist(verrou: string, cause: unknown): void {
  const e = cause as { code?: string; syscall?: string; path?: string } | undefined;
  if (
    !e || e.code !== "EEXIST" || e.syscall !== "mkdir" ||
    typeof e.path !== "string" || l0Resoudre(e.path) !== l0Resoudre(verrou)
  ) {
    throw new TemoinSansCauseError(
      `TemoinSansCauseError : la cause n'est pas un EEXIST de mkdir sur ` +
        `${l0Resoudre(verrou)} — code ${String(e?.code)}, syscall ${String(e?.syscall)}, ` +
        `path ${String(e?.path)} ; aucun témoin n'est créé`,
    );
  }
  const p = process.getBuiltinModule("node:path");
  l0Journal(verrou, "eexist");
  const dossier = p.join(l0Magasin(verrou), "temoins");
  for (const wait_id of l0DemandesValides(verrou)) {
    l0EcrireAtomique(
      dossier,
      `${wait_id}.${process.pid}.json`,
      JSON.stringify({ wait_id, lock_path: l0Resoudre(verrou), emitter_pid: process.pid, cause_code: "EEXIST" }),
    );
    l0Journal(verrou, `temoin ${wait_id}`);
  }
}

type L0Vu = { nom: string; recevable: boolean; motif: string };

/** Tous les témoins du verrou, classés contre la demande courante — cinq conditions. */
function l0TemoinsVus(verrou: string, wait_id: string): L0Vu[] {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  const dossier = p.join(l0Magasin(verrou), "temoins");
  const vus: L0Vu[] = [];
  let noms: string[];
  try {
    noms = fs.readdirSync(dossier);
  } catch {
    return vus;
  }
  for (const nom of noms.sort()) {
    if (nom.startsWith(".") || nom.endsWith(".tmp")) continue;
    let t: { wait_id?: unknown; lock_path?: unknown; emitter_pid?: unknown; cause_code?: unknown };
    try {
      t = JSON.parse(fs.readFileSync(p.join(dossier, nom), "utf-8"));
    } catch {
      vus.push({ nom, recevable: false, motif: "illisible" });
      continue;
    }
    const motifs: string[] = [];
    if (t?.wait_id !== wait_id) motifs.push("wait_id différent");
    if (typeof t?.lock_path !== "string" || l0Resoudre(t.lock_path) !== l0Resoudre(verrou)) {
      motifs.push("verrou différent");
    }
    if (!Number.isInteger(t?.emitter_pid) || (t.emitter_pid as number) <= 0) motifs.push("PID invalide");
    else if (t.emitter_pid === process.pid) motifs.push("PID = soi");
    if (t?.cause_code !== "EEXIST") motifs.push("cause différente");
    if (nom !== `${String(t?.wait_id)}.${String(t?.emitter_pid)}.json`) motifs.push("nom incohérent");
    vus.push({ nom, recevable: motifs.length === 0, motif: motifs.join(" + ") });
  }
  return vus;
}

/**
 * L'attente stricte (§ 9). Elle réutilise la demande prépubliée par `withSpaceGuard`
 * pour ce verrou dans ce processus ; hors de ce contexte, elle publie la sienne avant la
 * première évaluation de la condition, et la retire en `finally`.
 */
function attendreOuLever(cond: () => boolean, verrouAttendu: string, nom: string): void {
  const prepubliee = l0DemandesPrepubliees.get(l0Resoudre(verrouAttendu));
  const demande: L0Demande = prepubliee !== undefined
    ? { wait_id: prepubliee, lock_path: l0Resoudre(verrouAttendu) }
    : l0PublierDemande(verrouAttendu);
  const proprietaire = prepubliee === undefined;
  const etiquette = nom.replace(/\s+/g, "_");
  l0Journal(verrouAttendu, `attente ${demande.wait_id} ${proprietaire ? "propre" : "reutilisee"} ${etiquette}`);
  const t0 = Date.now();
  try {
    for (;;) {
      if (cond()) {
        l0Journal(verrouAttendu, `condition ${demande.wait_id} ${etiquette}`);
        return;
      }
      const vus = l0TemoinsVus(verrouAttendu, demande.wait_id);
      const accepte = vus.find((v) => v.recevable);
      if (accepte) {
        l0Journal(verrouAttendu, `accepte ${demande.wait_id} ${accepte.nom} ${etiquette}`);
        return;
      }
      const ecoule = Date.now() - t0;
      if (ecoule >= 10000) {
        l0Journal(verrouAttendu, `expire ${demande.wait_id} ${etiquette}`);
        const demandes = l0DemandesValides(verrouAttendu);
        const temoins = vus.length === 0
          ? "aucun"
          : vus.map((v) => `${v.nom}:${v.recevable ? "recevable" : `refusé(${v.motif})`}`).join(", ");
        throw new Error(
          `CHIEN DE GARDE — attente « ${nom} » expirée après ${ecoule} ms ; ` +
            `verrou attendu ${l0Resoudre(verrouAttendu)} ; wait_id ${demande.wait_id} ` +
            `(${proprietaire ? "propre" : "prépubliée"}) ; demandes vues ` +
            `${demandes.length === 0 ? "aucune" : demandes.join(", ")} ; témoins vus ${temoins}`,
        );
      }
      pause(5);
    }
  } finally {
    if (proprietaire) l0RetirerDemande(demande);
  }
}

// ------------------------------------------------ lecture autoritaire (§ 4 et § 5)

type L0Lecture =
  | { etat: "absent" }
  | { etat: "valide"; m: RunManifest }
  | { etat: "invalide"; motif: string };

/**
 * `readManifest` seul décide. `undefined` → absent ; `RecoveryError` → invalide ; toute
 * autre levée est un incident d'infrastructure et se propage : jamais un « valide » par
 * défaut, jamais un « invalide » qui cacherait une panne.
 */
function l0LireAutorite(dir: string): L0Lecture {
  try {
    const m = readManifest(dir);
    return m === undefined ? { etat: "absent" } : { etat: "valide", m };
  } catch (err) {
    if (err instanceof RecoveryError) return { etat: "invalide", motif: err.message };
    throw err;
  }
}

/**
 * Lecture mise en scène d'une archive (§ 5) : ses octets dans l'`active-run.json` d'un
 * répertoire temporaire neuf, `readManifest` sur ce répertoire, suppression en `finally`.
 * Archive absente ou illisible → inconnue. Panne du répertoire temporaire → levée.
 */
function l0LireArchive(dir: string, nom: string): L0Lecture {
  const fs = process.getBuiltinModule("node:fs");
  const os = process.getBuiltinModule("node:os");
  const p = process.getBuiltinModule("node:path");
  const source = p.join(dir, nom);
  if (!fs.existsSync(source)) return { etat: "absent" };
  let octets: Uint8Array;
  try {
    octets = fs.readFileSync(source);
  } catch (err) {
    return { etat: "invalide", motif: `archive illisible : ${String((err as Error)?.message ?? err)}` };
  }
  const scene = fs.mkdtempSync(p.join(os.tmpdir(), "l0-archive-"));
  try {
    fs.writeFileSync(p.join(scene, "active-run.json"), octets);
    return l0LireAutorite(scene);
  } finally {
    fs.rmSync(scene, { recursive: true, force: true });
  }
}

/** `ended` concordant (§ 5) : objet, `at` et `by` chaînes non vides, `outcome === status`. */
function l0EndedConcordant(m: RunManifest): boolean {
  const e = (m as { ended?: unknown }).ended as Record<string, unknown> | undefined;
  return !!e && typeof e === "object" &&
    typeof e.at === "string" && e.at.length > 0 &&
    typeof e.by === "string" && e.by.length > 0 &&
    e.outcome === m.status;
}

function l0EstTerminal(l: L0Lecture, R: string): boolean {
  return l.etat === "valide" && l.m.runId === R &&
    (l.m.status === "completed" || l.m.status === "abandoned") && l0EndedConcordant(l.m);
}

/** § 5. R est un paramètre, jamais redéduit du successeur courant. */
function publicationTerminale(dir: string, R: string): boolean {
  const courant = l0LireAutorite(dir);
  if (l0EstTerminal(courant, R)) return true;
  if (!l0EstTerminal(l0LireArchive(dir, `${R}-run.json`), R)) return false;
  if (courant.etat === "absent") return true;
  return courant.etat === "valide" && courant.m.runId !== R;
}

/**
 * Identification de R (§ 5) : le manifeste courant s'il est valide ; s'il est absent,
 * l'UNIQUE archive valide nommée exactement `${runId}-run.json` ; sinon inconnu.
 */
function l0RunAttendu(dir: string): string | undefined {
  const fs = process.getBuiltinModule("node:fs");
  const courant = l0LireAutorite(dir);
  if (courant.etat === "valide") return courant.m.runId;
  if (courant.etat === "invalide") return undefined;
  const candidates: string[] = [];
  for (const nom of fs.readdirSync(dir).sort()) {
    if (!nom.endsWith("-run.json") || nom === "active-run.json") continue;
    const a = l0LireArchive(dir, nom);
    if (a.etat === "valide" && nom === `${a.m.runId}-run.json`) candidates.push(a.m.runId);
  }
  return candidates.length === 1 ? candidates[0] : undefined;
}

/** La condition d'une ouverture : R capté une fois, puis fixé. */
function l0ConditionPublication(dir: string): () => boolean {
  let R = l0RunAttendu(dir);
  return () => {
    if (R === undefined) R = l0RunAttendu(dir);
    return R !== undefined && publicationTerminale(dir, R);
  };
}

/* ================================================================ fin instrument L0 */

/** Depuis quand ce verrou est-il là ? Un vestige de crash se reconnaît à son âge. */

