class TemoinSansCauseError extends Error {}

const L0_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** Demandes prépubliées par `withSpaceGuard` dans CE processus : verrou absolu → wait_id. */
const l0DemandesPrepubliees = new Map<string, string>();

function l0Resoudre(verrou: string): string {
  return process.getBuiltinModule("node:path").resolve(verrou);
}

/** Le magasin d'un verrou : SHA-256 complet de son chemin absolu. */
function l0Magasin(verrou: string): string {
  const os = process.getBuiltinModule("node:os");
  const p = process.getBuiltinModule("node:path");
  const c = process.getBuiltinModule("node:crypto");
  const empreinte = c.createHash("sha256").update(l0Resoudre(verrou)).digest("hex");
  return p.join(os.tmpdir(), "l0-temoins-eexist", empreinte);
}

/**
 * Le journal d'ordre. Un ajout O_APPEND est atomique et ordonné par le noyau : l'ordre
 * des lignes EST l'ordre des événements, sans comparaison d'horloges entre processus.
 */
function l0Journal(verrou: string, ligne: string): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  const m = l0Magasin(verrou);
  fs.mkdirSync(m, { recursive: true });
  fs.appendFileSync(p.join(m, "journal"), `${ligne} pid=${process.pid}\n`);
}

/** Écrit sous un nom temporaire propre, puis rend visible par `rename`. */
function l0EcrireAtomique(dossier: string, nom: string, corps: string): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  fs.mkdirSync(dossier, { recursive: true });
  const provisoire = p.join(dossier, `.${nom}.${process.pid}.tmp`);
  fs.writeFileSync(provisoire, corps);
  fs.renameSync(provisoire, p.join(dossier, nom));
}

type L0Demande = { wait_id: string; lock_path: string };

/** Publie une demande pour ce verrou. Le journal est écrit APRÈS le `rename`. */
function l0PublierDemande(verrou: string): L0Demande {
  const p = process.getBuiltinModule("node:path");
  const c = process.getBuiltinModule("node:crypto");
  const wait_id = c.randomUUID();
  const lock_path = l0Resoudre(verrou);
  l0EcrireAtomique(
    p.join(l0Magasin(verrou), "demandes"),
    `${wait_id}.json`,
    JSON.stringify({ wait_id, lock_path, waiter_pid: process.pid }),
  );
  l0Journal(verrou, `demande ${wait_id}`);
  return { wait_id, lock_path };
}

function l0RetirerDemande(d: L0Demande): void {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  fs.rmSync(p.join(l0Magasin(d.lock_path), "demandes", `${d.wait_id}.json`), { force: true });
  l0Journal(d.lock_path, `retrait ${d.wait_id}`);
}

/** Les demandes valides du verrou exact : nom, contenu, PID positif et verrou cohérents. */
function l0DemandesValides(verrou: string): string[] {
  const fs = process.getBuiltinModule("node:fs");
  const p = process.getBuiltinModule("node:path");
  const dossier = p.join(l0Magasin(verrou), "demandes");
  let noms: string[];
  try {
    noms = fs.readdirSync(dossier);
  } catch {
    return [];
  }
  const valides: string[] = [];
  for (const nom of noms.sort()) {
    const m = /^(.+)\.json$/.exec(nom);
    if (!m || nom.startsWith(".") || !L0_UUID.test(m[1])) continue;
    let d: { wait_id?: unknown; lock_path?: unknown; waiter_pid?: unknown };
    try {
      d = JSON.parse(fs.readFileSync(p.join(dossier, nom), "utf-8"));
    } catch {
